<script setup lang="ts">import {ref,computed} from 'vue';import {Plus,ChevronLeft,ChevronRight,LayoutGrid,List,X} from 'lucide-vue-next';import WorkshopHeader from '../../components/WorkshopHeader.vue';import StatusBadge from '../../components/StatusBadge.vue';import {useWorkshop} from '../../composables/useWorkshop';import type {BookingStatus} from '../../data/company';const {state,setBookingStatus,addBooking}=useWorkshop();const view=ref<'Day'|'Week'>('Day');const selected=ref('2026-08-26');const adding=ref(false);const form=ref({time:'15:00',duration:'1h',customer:'New customer',vehicle:'BMW 118i',registration:'LJ NC-101',service:'Regular service',technician:'Luka Zupan',bay:'Lift 3'});const statusOptions:BookingStatus[]=['Requested','Confirmed','Arrived','In workshop','Waiting approval','Ready','Completed','Cancelled'];const shown=computed(()=>view.value==='Day'?state.bookings.filter(b=>b.date===selected.value):state.bookings);const save=()=>{addBooking({id:crypto.randomUUID(),date:selected.value,...form.value,status:'Confirmed',source:'Manual'});adding.value=false}
</script>
<template><WorkshopHeader title="Calendar" subtitle="Ljubljana Center"><button @click="adding=true" class="btn-primary !min-h-10"><Plus :size="16"/>Booking</button></WorkshopHeader><div class="mx-auto max-w-[1400px] p-5 md:p-8"><div class="flex flex-wrap items-center justify-between gap-4"><div class="flex items-center gap-2"><button class="btn-secondary !min-h-10 !px-3"><ChevronLeft :size="17"/></button><input v-model="selected" type="date" class="field nums w-auto"/><button class="btn-secondary !min-h-10 !px-3"><ChevronRight :size="17"/></button></div><div class="flex rounded-xl border bg-white p-1"><button v-for="v in ['Day','Week']" @click="view=v as 'Day'|'Week'" class="flex items-center gap-2 rounded-lg px-4 py-2 text-sm font-medium" :class="view===v?'bg-ink text-white':''"><component :is="v==='Day'?List:LayoutGrid" :size="16"/>{{v}}</button></div></div><div class="mt-6 overflow-hidden rounded-2xl border bg-white"><div class="hidden grid-cols-[80px_1fr_150px_140px_160px] gap-4 border-b bg-stone-50 px-5 py-3 text-xs font-semibold text-muted md:grid"><span>Time</span><span>Booking</span><span>Technician</span><span>Bay</span><span>Status</span></div><div v-for="b in shown" class="grid gap-3 border-b p-5 last:border-0 md:grid-cols-[80px_1fr_150px_140px_160px] md:items-center md:gap-4"><span class="nums font-semibold">{{b.time}}<small class="block font-normal text-muted">{{b.duration}}</small></span><span><strong class="block text-sm">{{b.vehicle}} · {{b.registration}}</strong><small class="text-muted">{{b.customer}} · {{b.service}} · {{b.source}}</small></span><span class="text-sm">{{b.technician}}</span><span class="text-sm text-muted">{{b.bay}}</span><select :value="b.status" @change="setBookingStatus(b.id,($event.target as HTMLSelectElement).value as BookingStatus)" class="rounded-lg border px-2 py-2 text-xs font-semibold"><option v-for="s in statusOptions">{{s}}</option></select></div></div></div><Teleport to="body"><div v-if="adding" class="fixed inset-0 z-[90] flex items-end bg-black/30" @click.self="adding=false"><form @submit.prevent="save" class="mx-auto w-full max-w-xl rounded-t-3xl bg-white p-6 pb-10"><div class="flex justify-between"><h2 class="text-2xl font-semibold">Manual booking</h2><button type="button" @click="adding=false" class="grid h-10 w-10 place-items-center rounded-full bg-stone-100"><X :size="18"/></button></div><div class="mt-6 grid grid-cols-2 gap-3"><label><span class="label">Time</span><input v-model="form.time" type="time" class="field"/></label><label><span class="label">Duration</span><select v-model="form.duration" class="field"><option>45m</option><option>1h</option><option>1h 30m</option><option>2h</option></select></label></div><label class="mt-4 block"><span class="label">Customer</span><input v-model="form.customer" class="field"/></label><div class="mt-4 grid grid-cols-2 gap-3"><label><span class="label">Vehicle</span><input v-model="form.vehicle" class="field"/></label><label><span class="label">Registration</span><input v-model="form.registration" class="field"/></label></div><label class="mt-4 block"><span class="label">Service</span><input v-model="form.service" class="field"/></label><div class="mt-4 grid grid-cols-2 gap-3"><label><span class="label">Technician</span><select v-model="form.technician" class="field"><option>Luka Zupan</option><option>Marko Vidmar</option></select></label><label><span class="label">Bay / lift</span><input v-model="form.bay" class="field"/></label></div><button class="btn-primary mt-6 w-full">Create booking</button></form></div></Teleport></template>
